// Package store persists cache entries.
package store

// Entry is one cache entry.
type Entry struct {
	Key   string `json:"key"`
	Value string `json:"value"`
	TTL   int    `json:"ttl"`
}

input.content:
package store

import (
	"encoding/json"
	"io"
)

// Save writes entries to w as newline-delimited JSON, one object per line.
func Save(w io.Writer, entries []Entry) error {
	enc := json.NewEncoder(w)
	for _, e := range entries {
		if err := enc.Encode(e); err != nil {
			return err
		}
	}
	return nil
}

