package store

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
)

func TestSaveWritesNewlineDelimitedJSON(t *testing.T) {
	entries := []Entry{
		{Key: "a", Value: "1", TTL: 10},
		{Key: "b", Value: "2", TTL: 20},
	}

	var buf bytes.Buffer
	if err := Save(&buf, entries); err != nil {
		t.Fatalf("Save returned error: %v", err)
	}

	lines := strings.Split(strings.TrimRight(buf.String(), "\n"), "\n")
	if len(lines) != len(entries) {
		t.Fatalf("got %d lines, want %d", len(lines), len(entries))
	}

	for i, line := range lines {
		var got Entry
		if err := json.Unmarshal([]byte(line), &got); err != nil {
			t.Fatalf("line %d is not valid JSON: %v", i, err)
		}
		if got != entries[i] {
			t.Errorf("line %d = %+v, want %+v", i, got, entries[i])
		}
	}
}

func TestSaveEmpty(t *testing.T) {
	var buf bytes.Buffer
	if err := Save(&buf, nil); err != nil {
		t.Fatalf("Save returned error: %v", err)
	}
	if buf.Len() != 0 {
		t.Fatalf("expected empty output, got %q", buf.String())
	}
}

